// Toy CPU: 256 cells, registers R0/R1, PC. Each instruction = 2 bytes.
// Instruction byte: bits 7-6 opcode, bit 5 register select (0=R0,1=R1).
// Opcodes: 00=LOAD, 01=STORE, 10=ADD, 11=JUMP. Operand byte = address.
const mem = new Array(256).fill(0);
// Program at 0-7 (instruction byte, operand byte):
mem[0]=0x00; mem[1]=0xC8; // LOAD R0, 200
mem[2]=0x20; mem[3]=0xC9; // LOAD R1, 201
mem[4]=0x80; mem[5]=0x00; // ADD R0, R1
mem[6]=0x40; mem[7]=0xCA; // STORE 202, R0
// Data:
mem[200]=25; mem[201]=17; mem[202]=0;
let R=[0,0], PC=0;
const PROGRAM_END=8;
while (PC < PROGRAM_END) {
  const instr=mem[PC], operand=mem[PC+1];
  const opcode=(instr>>6)&0b11;
  const reg=(instr>>5)&0b1;
  // --- implement the four opcodes below ---
  if (opcode===0b00) {            // LOAD Rreg, operand
    R[reg]=mem[operand]; PC+=2;
  } else if (opcode===0b01) {     // STORE operand, Rreg
    mem[operand]=R[reg]; PC+=2;
  } else if (opcode===0b10) {     // ADD R0,R1 -> R0
    R[0]=R[0]+R[1]; PC+=2;
  } else if (opcode===0b11) {     // JUMP operand
    PC=operand;
  }
}
console.log('mem[202] = ' + mem[202]);
